export interface ConnectorConfig {
  INTERCOM_ACCESS_TOKEN: string;
  NOTION_TOKEN: string;
  NOTION_PARENT_PAGE_ID: string;
  fetch?: typeof fetch;
}

export interface IntercomConversationPart {
  id: string;
  part_type: string;
  author: {
    type: 'user' | 'admin';
    id: string;
  };
  body: string;
  created_at: number;
}

export interface ConnectorInput {
  conversation?: {
    id: string;
    participants?: Array<{
      id: string;
      type: string;
      email?: string;
      phone?: string;
    }>;
  };
  conversation_parts?: IntercomConversationPart[];
  pages?: {
    next?: string;
  };
}

export interface ConnectorResult {
  notionPageId: string;
  conversationId: string;
  partsCount: number;
}

const EMAIL_REGEX = /\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi;
const PHONE_REGEX = /\+?[0-9\s\-\(\)]{10,}/g;

function redactText(text: string): string {
  return text
    .replace(EMAIL_REGEX, '[REDACTED EMAIL]')
    .replace(PHONE_REGEX, '[REDACTED PHONE]');
}

function buildNotionRichTextBlock(content: string): object {
  const redacted = redactText(content);
  return {
    object: 'block',
    type: 'paragraph',
    paragraph: {
      rich_text: [
        {
          type: 'text',
          text: {
            content: redacted,
            link: null,
          },
          annotations: {
            bold: false,
            italic: false,
            strikethrough: false,
            underline: false,
            code: false,
            color: 'default',
          },
          plain_text: redacted,
          href: null,
        },
      ],
    },
  };
}

async function fetchAllConversationParts(
  conversationId: string,
  accessToken: string,
  fetchFn: typeof fetch,
): Promise<IntercomConversationPart[]> {
  const allParts: IntercomConversationPart[] = [];
  let nextUrl = `https://api.intercom.io/conversations/${conversationId}/parts`;

  while (nextUrl) {
    const response = await fetchFn(nextUrl, {
      method: 'GET',
      headers: {
        Authorization: `Bearer ${accessToken}`,
        Accept: 'application/json',
      },
    });

    if (!response.ok) {
      throw new Error(`Intercom API error: ${response.status} ${response.statusText} for ${nextUrl}`);
    }

    const data = (await response.json()) as {
      conversation_parts: IntercomConversationPart[];
      pages: { next: string | null };
    };

    allParts.push(...data.conversation_parts);
    nextUrl = data.pages.next ?? '';
  }

  return allParts;
}

export async function handle(payload: ConnectorInput, config: ConnectorConfig): Promise<ConnectorResult> {
  const fetchFn = config.fetch ?? fetch;

  let conversationId: string;
  let parts: IntercomConversationPart[];

  if (payload.conversation_parts && payload.conversation_parts.length > 0) {
    parts = payload.conversation_parts;
    const nextUrl = payload.pages?.next;
    if (nextUrl) {
      const match = nextUrl.match(/\/conversations\/([^/]+)\/parts/);
      conversationId = match?.[1] ?? 'unknown';
    } else {
      conversationId = 'unknown';
    }
  } else if (payload.conversation?.id) {
    conversationId = payload.conversation.id;
    parts = await fetchAllConversationParts(conversationId, config.INTERCOM_ACCESS_TOKEN, fetchFn);
  } else {
    throw new Error('Missing required field: either conversation.id or conversation_parts must be provided');
  }

  if (parts.length === 0) {
    throw new Error('No conversation parts found to create transcript');
  }

  const children = parts.map((part) => {
    const authorLabel = part.author.type === 'user' ? 'User' : 'Support';
    const content = `${authorLabel} (${part.author.id}): ${part.body}`;
    return buildNotionRichTextBlock(content);
  });

  const notionPayload = {
    parent: {
      type: 'page_id',
      page_id: config.NOTION_PARENT_PAGE_ID,
    },
    properties: {
      title: {
        title: [
          {
            text: {
              content: `Intercom Conversation Transcript - ${conversationId}`,
            },
          },
        ],
      },
    },
    children,
  };

  const notionResponse = await fetchFn('https://api.notion.com/v1/pages', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.NOTION_TOKEN}`,
      'Content-Type': 'application/json',
      'Notion-Version': '2022-06-28',
    },
    body: JSON.stringify(notionPayload),
  });

  if (!notionResponse.ok) {
    throw new Error(`Notion API error: ${notionResponse.status} ${notionResponse.statusText} for https://api.notion.com/v1/pages`);
  }

  const notionData = (await notionResponse.json()) as { id: string };

  return {
    notionPageId: notionData.id,
    conversationId,
    partsCount: parts.length,
  };
}

import { describe, it, expect, vi } from 'vitest';
import { handle, ConnectorConfig, ConnectorInput } from './connector';
import { SOURCE_EXAMPLE, contractFetch, fakeFetch, jsonResponse } from './fixtures';

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch();
    const config: ConnectorConfig = {
      INTERCOM_ACCESS_TOKEN: 'test-intercom-token',
      NOTION_TOKEN: 'test-notion-token',
      NOTION_PARENT_PAGE_ID: '1234567890abcdef1234567890abcdef',
      fetch,
    };
    const result = await handle(SOURCE_EXAMPLE as unknown as ConnectorInput, config);
    expect(calls.length).toBeGreaterThan(0);
    expect(result.notionPageId).toBe('a1b2c3d4-e5f6-7890-g1h2-i3j4k5l6m7n8');
    expect(result.conversationId).toBe('conv_987');
    expect(result.partsCount).toBe(2);
  });
});

describe('handle', () => {
  it('creates Notion page with redacted transcript when conversation_parts provided', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://api.notion.com/v1/pages' && req.method === 'POST') {
        return jsonResponse({ id: 'page-123' }, 201);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const config: ConnectorConfig = {
      INTERCOM_ACCESS_TOKEN: 'intercom-token',
      NOTION_TOKEN: 'notion-token',
      NOTION_PARENT_PAGE_ID: 'parent-page-id',
      fetch,
    };

    const input: ConnectorInput = {
      conversation_parts: [
        {
          id: 'part-1',
          part_type: 'comment',
          author: { type: 'user', id: 'user-1' },
          body: 'Contact me at test@example.com or +1-555-123-4567',
          created_at: 1717020000,
        },
        {
          id: 'part-2',
          part_type: 'comment',
          author: { type: 'admin', id: 'admin-1' },
          body: 'Sure, I will help.',
          created_at: 1717020060,
        },
      ],
      pages: { next: null },
    };

    const result = await handle(input, config);

    expect(result.notionPageId).toBe('page-123');
    expect(result.partsCount).toBe(2);
    expect(calls.length).toBe(1);

    const notionCall = calls[0];
    expect(notionCall.method).toBe('POST');
    expect(notionCall.url).toBe('https://api.notion.com/v1/pages');
    expect(notionCall.headers.get('authorization')).toBe('Bearer notion-token');
    expect(notionCall.headers.get('notion-version')).toBe('2022-06-28');

    const body = notionCall.json as {
      children: Array<{ paragraph: { rich_text: Array<{ text: { content: string } }> } }>;
    };
    expect(body.children.length).toBe(2);
    expect(body.children[0].paragraph.rich_text[0].text.content).toContain('[REDACTED EMAIL]');
    expect(body.children[0].paragraph.rich_text[0].text.content).toContain('[REDACTED PHONE]');
    expect(body.children[1].paragraph.rich_text[0].text.content).toBe('Support (admin-1): Sure, I will help.');
  });

  it('fetches all pages from Intercom when conversation.id provided', async () => {
    const intercomCalls: Array<{ url: string; method: string }> = [];
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.startsWith('https://api.intercom.io/conversations/') && req.method === 'GET') {
        intercomCalls.push({ url: req.url, method: req.method });
        if (req.url.includes('starting_after=part-1')) {
          return jsonResponse({
            conversation_parts: [
              {
                id: 'part-2',
                part_type: 'comment',
                author: { type: 'admin', id: 'admin-1' },
                body: 'Second message',
                created_at: 1717020060,
              },
            ],
            pages: { next: null },
          });
        }
        return jsonResponse({
          conversation_parts: [
            {
              id: 'part-1',
              part_type: 'comment',
              author: { type: 'user', id: 'user-1' },
              body: 'First message',
              created_at: 1717020000,
            },
          ],
          pages: { next: 'https://api.intercom.io/conversations/conv-456/parts?starting_after=part-1' },
        });
      }
      if (req.url === 'https://api.notion.com/v1/pages' && req.method === 'POST') {
        return jsonResponse({ id: 'page-789' }, 201);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const config: ConnectorConfig = {
      INTERCOM_ACCESS_TOKEN: 'intercom-token',
      NOTION_TOKEN: 'notion-token',
      NOTION_PARENT_PAGE_ID: 'parent-page-id',
      fetch,
    };

    const input: ConnectorInput = {
      conversation: { id: 'conv-456' },
    };

    const result = await handle(input, config);

    expect(result.notionPageId).toBe('page-789');
    expect(result.conversationId).toBe('conv-456');
    expect(result.partsCount).toBe(2);
    expect(intercomCalls.length).toBe(2);
    expect(intercomCalls[0].url).toBe('https://api.intercom.io/conversations/conv-456/parts');
    expect(intercomCalls[1].url).toBe('https://api.intercom.io/conversations/conv-456/parts?starting_after=part-1');
    expect(calls.length).toBe(3); // 2 Intercom + 1 Notion
  });

  it('throws when required field is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const config: ConnectorConfig = {
      INTERCOM_ACCESS_TOKEN: 'token',
      NOTION_TOKEN: 'token',
      NOTION_PARENT_PAGE_ID: 'parent',
      fetch,
    };

    const input: ConnectorInput = {};

    await expect(handle(input, config)).rejects.toThrow('Missing required field: either conversation.id or conversation_parts must be provided');
  });

  it('throws on non-2xx Intercom response', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.startsWith('https://api.intercom.io/conversations/')) {
        return jsonResponse({ error: 'unauthorized' }, 401);
      }
      return jsonResponse({}, 200);
    });

    const config: ConnectorConfig = {
      INTERCOM_ACCESS_TOKEN: 'bad-token',
      NOTION_TOKEN: 'notion-token',
      NOTION_PARENT_PAGE_ID: 'parent',
      fetch,
    };

    const input: ConnectorInput = { conversation: { id: 'conv-1' } };

    await expect(handle(input, config)).rejects.toThrow('Intercom API error: 401 Unauthorized for https://api.intercom.io/conversations/conv-1/parts');
    expect(calls.length).toBe(1);
  });

  it('throws on non-2xx Notion response', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://api.notion.com/v1/pages') {
        return jsonResponse({ error: 'forbidden' }, 403);
      }
      return jsonResponse({}, 200);
    });

    const config: ConnectorConfig = {
      INTERCOM_ACCESS_TOKEN: 'intercom-token',
      NOTION_TOKEN: 'bad-notion-token',
      NOTION_PARENT_PAGE_ID: 'parent',
      fetch,
    };

    const input: ConnectorInput = {
      conversation_parts: [
        {
          id: 'part-1',
          part_type: 'comment',
          author: { type: 'user', id: 'user-1' },
          body: 'Hello',
          created_at: 1717020000,
        },
      ],
      pages: { next: null },
    };

    await expect(handle(input, config)).rejects.toThrow('Notion API error: 403 Forbidden for https://api.notion.com/v1/pages');
    expect(calls.length).toBe(1);
  });

  it('uses injected fetch and includes auth headers', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://api.notion.com/v1/pages') {
        return jsonResponse({ id: 'page-auth' }, 201);
      }
      return jsonResponse({}, 200);
    });

    const config: ConnectorConfig = {
      INTERCOM_ACCESS_TOKEN: 'intercom-token',
      NOTION_TOKEN: 'notion-token',
      NOTION_PARENT_PAGE_ID: 'parent',
      fetch,
    };

    const input: ConnectorInput = {
      conversation_parts: [
        {
          id: 'part-1',
          part_type: 'comment',
          author: { type: 'user', id: 'user-1' },
          body: 'Test',
          created_at: 1717020000,
        },
      ],
      pages: { next: null },
    };

    await handle(input, config);

    const notionCall = calls.find((c) => c.url === 'https://api.notion.com/v1/pages');
    expect(notionCall).toBeDefined();
    expect(notionCall!.headers.get('authorization')).toBe('Bearer notion-token');
    expect(notionCall!.headers.get('content-type')).toBe('application/json');
  });

  it('maps fields correctly to Notion rich text blocks', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://api.notion.com/v1/pages') {
        return jsonResponse({ id: 'page-fields' }, 201);
      }
      return jsonResponse({}, 200);
    });

    const config: ConnectorConfig = {
      INTERCOM_ACCESS_TOKEN: 'token',
      NOTION_TOKEN: 'token',
      NOTION_PARENT_PAGE_ID: 'parent',
      fetch,
    };

    const input: ConnectorInput = {
      conversation_parts: [
        {
          id: 'part-1',
          part_type: 'comment',
          author: { type: 'user', id: 'user-abc' },
          body: 'Hello, I need help with my account.',
          created_at: 1717020000,
        },
        {
          id: 'part-2',
          part_type: 'comment',
          author: { type: 'admin', id: 'admin-def' },
          body: 'Sure, let me look into that for you.',
          created_at: 1717020060,
        },
      ],
      pages: { next: null },
    };

    await handle(input, config);

    const notionCall = calls.find((c) => c.url === 'https://api.notion.com/v1/pages');
    const body = notionCall!.json as {
      properties: { title: { title: Array<{ text: { content: string } }> } };
      children: Array<{ paragraph: { rich_text: Array<{ text: { content: string }; annotations: object }> } }>;
    };

    expect(body.properties.title.title[0].text.content).toBe('Intercom Conversation Transcript - unknown');
    expect(body.children.length).toBe(2);
    expect(body.children[0].paragraph.rich_text[0].text.content).toBe('User (user-abc): Hello, I need help with my account.');
    expect(body.children[1].paragraph.rich_text[0].text.content).toBe('Support (admin-def): Sure, let me look into that for you.');
    expect(body.children[0].paragraph.rich_text[0].annotations).toEqual({
      bold: false,
      italic: false,
      strikethrough: false,
      underline: false,
      code: false,
      color: 'default',
    });
  });

  it('throws when no conversation parts found', async () => {
    const { fetch } = fakeFetch((req) => {
      if (req.url.startsWith('https://api.intercom.io/conversations/')) {
        return jsonResponse({ conversation_parts: [], pages: { next: null } });
      }
      return jsonResponse({}, 200);
    });

    const config: ConnectorConfig = {
      INTERCOM_ACCESS_TOKEN: 'token',
      NOTION_TOKEN: 'token',
      NOTION_PARENT_PAGE_ID: 'parent',
      fetch,
    };

    const input: ConnectorInput = { conversation: { id: 'empty-conv' } };

    await expect(handle(input, config)).rejects.toThrow('No conversation parts found to create transcript');
  });
});

