// Source: https://developers.intercom.com/docs/references/rest-api/api.intercom.io/models/conversation_parts
// Source: https://developers.notion.com/reference/post-page

/** Example payload of the source event, as documented. */
export const SOURCE_EXAMPLE = {
  "conversation_parts": [
    {
      "id": "part_123",
      "part_type": "comment",
      "author": {
        "type": "user",
        "id": "user_abc"
      },
      "body": "Hello, I need help with my account.",
      "created_at": 1717020000
    },
    {
      "id": "part_124",
      "part_type": "comment",
      "author": {
        "type": "admin",
        "id": "admin_def"
      },
      "body": "Sure, let me look into that for you.",
